//! Writing the site (api-docs-generation "Build command"): only files a
//! previous build listed in `.rustman-docs-manifest` are replaced or
//! removed, and a non-empty folder without that manifest is refused unless
//! `--force` is given.

use std::collections::BTreeMap;
use std::path::Path;

use crate::error::DocsError;

/// Generated files, by `/`-separated path under `--out`, sorted.
pub type Files = BTreeMap<String, Vec<u8>>;

/// The manifest file, listing what the last build wrote.
pub const MANIFEST: &str = ".rustman-docs-manifest";

/// Refuse to write into `out` when it holds files and no manifest, unless
/// `force`. `shown` names the folder in the message (`site/`).
pub fn check_target(out: &Path, shown: &str, force: bool) -> Result<(), DocsError> {
    if force || out.join(MANIFEST).is_file() {
        return Ok(());
    }
    let mut entries = match std::fs::read_dir(out) {
        Ok(entries) => entries,
        Err(e) if e.kind() == std::io::ErrorKind::NotFound => return Ok(()),
        Err(e) => return Err(DocsError::io(out, e)),
    };
    if entries.next().is_some() {
        return Err(DocsError::NotEmpty(shown.to_owned()));
    }
    Ok(())
}

/// Write `files` into `out`: remove what the previous manifest listed and
/// this build does not produce, write every file, then the new manifest.
pub fn write(out: &Path, files: &Files) -> Result<(), DocsError> {
    for stale in previous(out) {
        if !files.contains_key(&stale) {
            remove(&out.join(&stale))?;
        }
    }
    for (name, bytes) in files {
        let path = out.join(name);
        if let Some(parent) = path.parent() {
            std::fs::create_dir_all(parent).map_err(|e| DocsError::io(parent, e))?;
        }
        std::fs::write(&path, bytes).map_err(|e| DocsError::io(&path, e))?;
    }
    let manifest: String = files.keys().map(|name| format!("{name}\n")).collect();
    let path = out.join(MANIFEST);
    std::fs::write(&path, manifest).map_err(|e| DocsError::io(&path, e))
}

/// Delete `name` under `out` if it is there (a file the leak scan refused).
pub fn remove_file(out: &Path, name: &str) -> Result<(), DocsError> {
    remove(&out.join(name))
}

/// The paths the previous build listed, never leaving `out`.
fn previous(out: &Path) -> Vec<String> {
    let Ok(text) = std::fs::read_to_string(out.join(MANIFEST)) else {
        return Vec::new();
    };
    text.lines()
        .filter(|line| is_contained(line))
        .map(str::to_owned)
        .collect()
}

/// A relative path made of plain names: no `..`, no root, no drive.
pub(crate) fn is_contained(path: &str) -> bool {
    !path.is_empty()
        && path.split('/').all(|part| {
            !part.is_empty() && part != "." && part != ".." && !part.contains(['\\', ':'])
        })
}

fn remove(path: &Path) -> Result<(), DocsError> {
    match std::fs::remove_file(path) {
        Ok(()) => Ok(()),
        Err(e) if e.kind() == std::io::ErrorKind::NotFound => Ok(()),
        Err(e) => Err(DocsError::io(path, e)),
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    fn files(names: &[&str]) -> Files {
        names
            .iter()
            .map(|n| ((*n).to_owned(), b"x\n".to_vec()))
            .collect()
    }

    #[test]
    fn a_foreign_folder_is_refused_unless_forced() {
        let dir = tempfile::tempdir().unwrap();
        let out = dir.path().join("site");
        check_target(&out, "site/", false).unwrap();
        std::fs::create_dir_all(&out).unwrap();
        check_target(&out, "site/", false).unwrap();
        std::fs::write(out.join("notes.txt"), "mine").unwrap();
        let err = check_target(&out, "site/", false).unwrap_err();
        assert_eq!(
            err.to_string(),
            "site/ is not empty and was not generated by rustman docs; use --force"
        );
        assert_eq!(err.exit_code(), 2);
        check_target(&out, "site/", true).unwrap();
    }

    #[test]
    fn only_generated_files_are_replaced() {
        let dir = tempfile::tempdir().unwrap();
        let out = dir.path();
        std::fs::write(out.join("CNAME"), "docs.example").unwrap();
        write(out, &files(&["index.html", "endpoints/a.html"])).unwrap();
        check_target(out, "site/", false).unwrap();
        write(out, &files(&["index.html", "endpoints/b.html"])).unwrap();
        assert!(!out.join("endpoints/a.html").exists());
        assert!(out.join("endpoints/b.html").exists());
        assert!(out.join("CNAME").exists(), "a file it did not write stays");
        let manifest = std::fs::read_to_string(out.join(MANIFEST)).unwrap();
        assert_eq!(manifest, "endpoints/b.html\nindex.html\n");
    }

    #[test]
    fn manifest_entries_never_leave_the_folder() {
        assert!(is_contained("endpoints/a.html"));
        for bad in ["", "../x", "/etc/passwd", "a//b", "C:/x", "a\\..\\b", "./a"] {
            assert!(!is_contained(bad), "{bad}");
        }
    }
}
